import dash
from dash import html, dcc
import pandas as pd
import numpy as np
import plotly.graph_objects as go
import plotly.express as px
from urllib.request import urlopen
import json
import io

np.random.seed(42)

# ======================================================
# PALETA GLOBAL CAI
# ======================================================

COLOR_CAI = "#1b9e77"
COLOR_NO_CAI = "#bdbdbd"

CAI_COLOR_MAP = {
    "Con CAI": COLOR_CAI,
    "Sin CAI": COLOR_NO_CAI
}

n_cai = 207
n_total = 8131
perc_cai = n_cai / n_total * 100
perc_no_cai = 100 - perc_cai


# -------- MAPA CCAA --------
with urlopen(
    "https://github.com/R-CoderDotCom/data/blob/main/shapefile_spain/spain.geojson?raw=true"
) as response:
    ccaa_geojson = json.load(response)

ccaa_cais = pd.DataFrame({
    "ccaa_id": [
        "01", "02", "03", "04", "05", "06", "07", "08", "09",
        "10", "11", "12", "13", "14", "15", "16", "17"
    ],
    "ccaa_name": [
        "Andalucía", "Aragón", "Asturias", "Baleares", "Canarias",
        "Cantabria", "Castilla-La Mancha", "Castilla y León", "Cataluña",
        "Comunidad Valenciana", "Extremadura", "Galicia", "Madrid",
        "Murcia", "Navarra", "País Vasco", "La Rioja"
    ],
    "num_cais": [31, 9, 4, 7, 8, 2, 5, 16, 54, 54, 0, 9, 10, 3, 14, 20, 4]
})

# ======================================================
# FIGURA 1 – MAPA CCAA (CHOROPLETH – MAPLIBRE)
# ======================================================

CAI_CONTINUOUS_SCALE = [
    [0.0, "#FFFFFF"],
    [0.1, COLOR_NO_CAI],
    [0.2, "#A0B7B0"],
    [0.4, "#88B2A6"],
    [0.6, "#64AB97"],
    [0.8, "#42A588"],
    [1.0, COLOR_CAI]
]

fig1 = px.choropleth_map(
    data_frame=ccaa_cais,
    geojson=ccaa_geojson,
    featureidkey="properties.ccaa_id",
    locations="ccaa_id",
    color="num_cais",
    color_continuous_scale=CAI_CONTINUOUS_SCALE,
    map_style="carto-positron",
    center=dict(lat=40.0, lon=-3.7),
    zoom=3.6,
    opacity=0.9,
    labels={"num_cais": "Nº CAIs"},
    title="Número de CAIs por CCAA",
    custom_data=["ccaa_name"]
)

fig1.update_traces(
    hovertemplate=(
        "<b>%{customdata[0]}</b><br>"
        "Nº CAIs: %{z}<extra></extra>"
    )
)

fig1.update_layout(
    margin=dict(l=0, r=0, t=50, b=0)
)

