income_cai = [float(x) for x in income_cai_raw.split() if x.strip()]
income_no_cai = [float(x) for x in income_no_cai_raw.split() if x.strip()]

fig2 = go.Figure()
fig2.add_trace(go.Box(
    y=income_cai,
    name="Con CAI",
    marker_color=COLOR_CAI,
    boxmean=True
))

fig2.add_trace(go.Box(
    y=income_no_cai,
    name="Sin CAI",
    marker_color=COLOR_NO_CAI,
    boxmean=True
))
fig2.update_layout(
    title="Renta de hogares según presencia de CAI",
    yaxis_title="Ingresos medios (€)"
)
